// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/healthz", wrapper.GetHealth)
	router.GET(options.BaseURL+"/readyz", wrapper.GetReady)
	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/auth/session", wrapper.GetSession)
	router.POST(options.BaseURL+"/auth/invitations/accept", wrapper.AcceptInvitation)
	router.POST(options.BaseURL+"/auth/password-reset/request", wrapper.RequestPasswordReset)
	router.POST(options.BaseURL+"/auth/password-reset/confirm", wrapper.ResetPassword)
	router.POST(options.BaseURL+"/auth/mfa/enroll", wrapper.EnrollMFA)
	router.POST(options.BaseURL+"/auth/mfa/enroll/confirm", wrapper.ConfirmMFAEnrollment)
	router.POST(options.BaseURL+"/auth/mfa/verify", wrapper.VerifyMFA)
	router.POST(options.BaseURL+"/auth/step-up", wrapper.StepUp)
	router.GET(options.BaseURL+"/organization", wrapper.GetOrganization)
	router.PATCH(options.BaseURL+"/organization", wrapper.UpdateOrganization)
	router.PATCH(options.BaseURL+"/organization/policy", wrapper.UpdateOrganizationPolicy)
	router.GET(options.BaseURL+"/users", wrapper.ListUsers)
	router.POST(options.BaseURL+"/users/invitations", wrapper.InviteUser)
	router.PATCH(options.BaseURL+"/users/:userId", wrapper.UpdateUser)
	router.GET(options.BaseURL+"/providers", wrapper.ListProviders)
	router.POST(options.BaseURL+"/providers", wrapper.CreateProvider)
	router.PATCH(options.BaseURL+"/providers/:providerId", wrapper.UpdateProvider)
	router.POST(options.BaseURL+"/providers/:providerId/rotate", wrapper.RotateProviderSecret)
	router.POST(options.BaseURL+"/providers/:providerId/deactivate", wrapper.DeactivateProvider)
	router.GET(options.BaseURL+"/operator/session", wrapper.GetOperatorSession)
	router.GET(options.BaseURL+"/operator/organizations", wrapper.ListOperatorOrganizations)
	router.POST(options.BaseURL+"/operator/organizations", wrapper.CreateOperatorOrganization)
	router.POST(options.BaseURL+"/operator/organizations/:organizationId/suspend", wrapper.SuspendOrganization)
	router.POST(options.BaseURL+"/operator/organizations/:organizationId/reinstate", wrapper.ReinstateOrganization)
	router.PATCH(options.BaseURL+"/operator/organizations/:organizationId/limits", wrapper.UpdateOrganizationLimits)
	router.GET(options.BaseURL+"/operator/audit", wrapper.ListOperatorAudit)
}
